insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1b513bf0-055a-46fd-973d-38cfb88f4ca0', 'es', '¿Qué formas de mirar favorecen una buena primera impresión?', '["Un contacto visual tranquilo", "Pausas naturales", "Una expresión amable", "Mirarla fijamente sin parpadear"]'::jsonb, 'Un contacto visual equilibrado y amable transmite confianza y naturalidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1b9394c8-71a4-4281-9046-5014c86b7514', 'es', 'Abres la conversación. Ella responde con calidez, pero luego su amiga la toma del brazo y se la lleva.', '["Cortés: estaba siendo amable antes de que la interrumpiera su amiga", "Abierta al principio, pero una interrupción externa lo cortó", "Fría: usó a su amiga como excusa para escaparse"]'::jsonb, 'Su respuesta cálida era abierta; la interrupción de su amiga es un factor externo, no una señal de ella.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1ccbf131-6df9-4829-afc6-793d8a586ba6', 'es', 'Ella te sonríe. Empiezas a planear tu frase de apertura. ¿Cuál es la mejor jugada?', '["Ensayar lo que vas a decir y luego ir", "Ir hacia ella de inmediato, aunque no tengas una frase pulida", "Esperar a que vuelva a mirarte para confirmarlo"]'::jsonb, 'Actuar rápido impide que la duda crezca. Muévete en los tres segundos después de verla.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('21c693ec-ce2c-4a1c-b6a4-e5c07cc9e39f', 'es', 'Hablas tan bajo que ella tiene que adivinar parte de lo que dices. ¿Qué genera esto?', '["Una atracción fuerte e inmediata", "Una presencia perfectamente ajustada", "Un aire misterioso e intrigante", "Un roce que estropea la fluidez"]'::jsonb, 'Hablar sin claridad añade una tensión innecesaria a la interacción.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('21ca0984-0243-415e-ab95-8d472e631a12', 'es', 'Te acercas a una mujer en la terraza de una cafetería. ¿Qué movimientos transmiten soltura?', '["Pasos rápidos y apresurados con los hombros encogidos", "Brazos rígidos pegados al cuerpo y andar tieso", "Ritmo constante, brazos que se mueven con naturalidad y postura erguida", "Pasos dudosos mirando al suelo"]'::jsonb, 'Moverte relajado transmite que no hay peligro y le hace más fácil la interacción.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('243e45da-4e6e-4747-bd72-4c71c92d582b', 'es', 'La ves, pero no vas bien vestido. ¿Qué deberías hacer?', '["Acercarte de todos modos", "No hacerlo; tu aspecto va a arruinar tus posibilidades", "Esperar hasta estar listo", "Mirarla a los ojos, pero sin hablarle"]'::jsonb, 'Si solo te acercas en condiciones perfectas, acabas haciendo muy pocos intentos. Puedes acercarte en cualquier momento.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('24ae814b-7816-4ac9-af4c-f56e4e9d8de9', 'es', '¿Por qué las aperturas indirectas se sienten menos como una interrupción?', '["Evitan el silencio", "Muestran seguridad", "Se suman al momento que los dos ya están viviendo"]'::jsonb, 'Un contexto compartido hace que tu entrada se sienta esperable y sea fácil responder.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('24ebc378-571a-47ca-a34d-406494e05bf1', 'es', 'Ves que está dibujando algo en su cuaderno. ¿Qué apertura muestra curiosidad?', '["“Tienes pinta de artista.”", "“¿Me puedo sentar aquí?”", "“Tienes talento, se nota.”", "“¿Qué estás dibujando? Se ve muy detallado.”"]'::jsonb, 'La curiosidad por sus experiencias invita a una conexión real, sin intenciones ocultas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('26e9ec88-6ad1-419a-a087-c91efb8998d2', 'es', '¿Qué hábitos te ayudan a ser constante al acercarte a largo plazo?', '["Hablar con gente todos los días", "Esperar a sentirte listo", "Conversar en lugares del día a día"]'::jsonb, 'Participar con regularidad baja la presión y hace que las interacciones se sientan más fáciles.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2726ad43-344c-4ec6-a996-4df4d37978f4', 'es', 'Ves a una mujer con un accesorio muy original. ¿Qué podrías decir primero para despertar curiosidad?', '["“¿Dónde lo conseguiste?”", "“Tengo una pregunta rápida sobre eso que llevas puesto.”", "“Qué bonito, me gusta.”", "“¿Eres de por aquí?”"]'::jsonb, 'El planteamiento crea curiosidad antes de revelar la pregunta.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('29a122e7-d801-4e7c-bf05-40a46aba0960', 'es', 'Ella está sola haciendo fila. Quieres pedirle su opinión. ¿Cuál es la mejor apertura?', '["“Hola, ¿qué tal tu día?”", "“Pregunta rápida: ¿eres más de café o de té?”", "“¿Qué crees que está mejor, la bebida de temporada o la de siempre?”"]'::jsonb, 'Plantear un dilema invita a dar su opinión, y eso la hace sentirse valorada e incluida.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2ada2eb4-7e4e-4ea9-b9d1-7cde29ea6304', 'es', 'Apenas se gira y te dice un “hola” sin ganas. ¿Qué indica esto?', '["Timidez", "Curiosidad", "Interés neutro", "Una respuesta fría"]'::jsonb, 'Una participación mínima significa que te retires; despídete bien.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2b69af0f-cead-4bcb-8f8d-580b110d13f2', 'es', '¿Qué señal indica con más claridad una actitud fría?', '["Sonreír brevemente", "Responder a tus preguntas", "Darte la espalda", "Reírse por cortesía"]'::jsonb, 'Un cuerpo orientado hacia otro lado indica desinterés. Retírate.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2d63f1fb-98b5-4678-aec8-6b0c2abded25', 'es', 'Se gira hacia ti, sonríe con calidez, responde con detalle, pero sigue mirando hacia sus amigas.', '["Abierta: hacer preguntas muestra interés aunque esté pendiente de sus amigas", "Cortés: es amable, pero las miradas repetidas muestran una atención dividida", "Neutra: solo está pendiente de sus amigas; sigue con normalidad"]'::jsonb, 'Sus respuestas indican una participación cortés, pero su atención no está del todo contigo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2f7b8ecd-021a-40d3-aea3-50d2530f7f6e', 'es', 'Te responde con calidez, pero sigue deslizando la pantalla de su celular. ¿Qué deberías suponer?', '["Que es tímida", "Que está abierta", "Que está distraída pero interesada", "Que está siendo cortés"]'::jsonb, 'Una atención dividida suele indicar cortesía, no interés real.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2fa1ad2f-3496-4f7e-b850-7253ba88fd6b', 'es', 'Se ríe con tu apertura y te mira de frente, pero cruza los brazos. ¿Qué está pasando?', '["Abierta: la risa y mirarte de frente muestran interés, a pesar de los brazos", "Cortés: una risa forzada con lenguaje corporal cerrado significa desinterés", "Mixta: la risa y mirarte de frente son abiertos, pero los brazos cruzados son duda"]'::jsonb, 'La risa indica comodidad y los brazos cruzados, reserva; sigue con un tono ligero.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3583c492-59dd-4eb4-a7c9-c98966901e7d', 'es', 'Ves que lleva una taza de café muy original. ¿Qué podrías decir primero para despertar curiosidad?', '["“Te tengo que preguntar algo sobre esa taza.”", "“¿Dónde conseguiste esa taza?”", "“Qué divertida tu taza.”", "“¿Vienes aquí a menudo?”"]'::jsonb, 'El planteamiento crea curiosidad antes de revelar la pregunta.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('36134173-386a-4742-a375-45b16eeb371f', 'es', '¿Qué exige marcar bien el tono?', '["Esperar a que ella te dé permiso o señales para seguir", "Elegir tú el tema en lugar de sumarte a su mundo", "Hacer avanzar la interacción sin esperar a que ella la lleve"]'::jsonb, 'Marcar el tono significa llevar el tema y el avance de la conversación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('365d84da-247e-427e-a603-8e7d2900f73f', 'es', 'Te responde con amabilidad, pero dice: “Creo que ya me tengo que ir pronto”. ¿Qué es esto?', '["Cortés con un límite suave: participa, pero indica que tiene poco tiempo", "Abierta: la respuesta amable muestra interés; lo de irse es solo cortesía", "Mixta: su participación choca con lo que dice de irse"]'::jsonb, 'Está siendo considerada mientras marca un límite; reconócelo y despídete con educación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3669c3ab-5f36-42cb-932f-6277589d1d8e', 'es', '¿Por qué es importante leer su primera reacción?', '["La obliga a estar abierta", "Mantiene la interacción cómoda para los dos", "Respeta su espacio y sus señales", "Evita cruzar límites que ella no ha abierto"]'::jsonb, 'Leer bien las señales mantiene la comodidad y el aplomo de los dos.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3717fc9d-129b-426e-a329-a0e904cfd1e1', 'es', 'Te da una respuesta corta, aparta la mirada y cambia el peso de un pie a otro. ¿Qué deberías hacer?', '["Ser breve y despedirte con elegancia", "Insistir con más preguntas para engancharla", "Avanzar para generar atracción", "Hacerle un cumplido para que entre en confianza"]'::jsonb, 'Las señales neutras o corteses significan que bajes el ritmo o te retires, para respetar su comodidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3763474f-7119-463b-a740-ab5dd1bb8606', 'es', 'Te acercas a ella mientras lee un libro en una cafetería. ¿Qué apertura mantiene una actitud firme?', '["“Perdón por molestarte, pero quería saludarte.”", "“¿Está ocupado este asiento?”", "“Ese libro se ve interesante. ¿De qué trata?”", "“Disculpa, ¿puedo hablar contigo un minuto?”"]'::jsonb, 'Ir directo y dar por hecho que habrá conversación marca el tono sin disculparte.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('381417bd-9910-49a2-b9c7-271afc73bcf9', 'es', '¿Qué resultados trae no hacer nada?', '["Un fracaso asegurado", "Protección contra el rechazo", "Ninguna conexión ni posibilidad", "Un arrepentimiento que dura"]'::jsonb, 'No hacer nada garantiza oportunidades perdidas y un arrepentimiento duradero.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('38ade8d0-fc3e-4396-9791-5b19775afa46', 'es', 'Te acercas a ella en un espacio abierto. ¿Qué deberías evitar?', '["Detenerte a una distancia social con una postura abierta", "Bloquearle una posible salida", "Acercarte en un ángulo de 45 grados, a la vista", "Dejar un metro de espacio"]'::jsonb, 'Bloquear las salidas incomoda, incluso en espacios abiertos.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3a61650f-61dd-4d87-b302-9c1fad8a6217', 'es', '¿Por qué el toque juguetón es importante al plantear la conversación?', '["Quita presión y hace que la interacción se sienta divertida en vez de seria", "Un planteamiento juguetón genera atracción a través de una experiencia emocional positiva", "Muestra que estás cómodo", "Todas las anteriores"]'::jsonb, 'Todo es cierto: el toque juguetón quita presión, genera emociones positivas y muestra que estás cómodo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3aa54f55-0812-4c14-be64-8fed1f814fb4', 'es', '¿Qué señal distingue mejor la receptividad de la cortesía?', '["Sonreír", "El contacto visual", "Hacerte preguntas a ti también", "Asentir"]'::jsonb, 'La reciprocidad es un indicador de interés más claro que las demás.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3b44889c-1e0c-4a51-8846-e7d4ea05c95b', 'es', 'Te acercas a ella mientras hace fila. Te dice: “La verdad es que tengo prisa”. ¿Cuál es la mejor respuesta?', '["“Tranquila, solo quería saludarte”, y te vas con naturalidad", "Pedirle perdón por molestarla y dar un paso atrás", "Ignorar lo que dijo y seguir hablando"]'::jsonb, 'No fuerces la conversación ni te disculpes; mantenlo ligero y sigue tu camino.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3c06a35a-c102-4ca8-bce5-02e0afa2b5a6', 'es', 'Discoteca. Se fueron con ella a una zona más tranquila. ¿Qué sigue?', '["Seguir conversando y proponer verse otro día", "Pedirle su contacto ahora, mientras el ritmo es bueno", "Proponer ir juntos a otro lugar", "Pedirle su número o proponer ir juntos a otro sitio, según la logística y sus señales"]'::jsonb, 'Con un buen ritmo toca dar el siguiente paso: asegurar el contacto o proponer seguir en otro lado si sus señales dicen que sí.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3c98c86a-c4c9-43a5-be53-6cad77bf34c5', 'es', '¿Cuándo deberías terminar una interacción?', '["Cuando da señales frías: participación mínima, cuerpo cerrado, girada hacia otro lado", "Cuando las señales de cortesía persisten: respuestas cortas, poca reciprocidad", "Cuando el tiempo o las circunstancias hacen que no tenga sentido seguir", "Todas las anteriores"]'::jsonb, 'Una despedida limpia protege su comodidad y tu actitud cuando no hay interés.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3caf0039-8d00-42c1-8c5a-9b57ae2ac717', 'es', 'Te dice: “La verdad es que estoy en medio de algo”, pero sigue sonriendo y mirándote de frente.', '["Abierta: la sonrisa pesa más que las palabras", "Cortés: marca un límite con respeto", "Mixta: insiste un poco", "Fría: cualquier límite es un rechazo"]'::jsonb, 'Un límite claro con calidez es una forma cortés de retirarse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3dfb88ca-871e-4a7e-b233-6335a1bd949a', 'es', 'Estás conversando y notas que su amiga está rondando cerca. ¿Cuál es la mejor jugada?', '["Ignorar a la amiga y seguir", "Competir por la atención", "Incluir brevemente a la amiga y luego volver a evaluar", "Avanzar de inmediato"]'::jsonb, 'Incluirla reduce la tensión social y te mantiene al mando.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3ebc28c1-d1f2-41ee-a393-af6d74a978a9', 'es', 'Se ríe, pero sigue girándose hacia otro lado. ¿Qué pesa más?', '["Su risa", "Tu apertura", "Su lenguaje corporal", "El lugar"]'::jsonb, 'Cuando las señales se contradicen, confía en las físicas; si se gira, dale espacio o retírate.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('40d53e0a-03ba-435a-8d62-e1fcb096eded', 'es', '¿Qué hace que una apertura indirecta se sienta natural y fácil de recibir?', '["Decir algo ingenioso o impresionante", "Un entorno o un momento que los dos están viviendo", "El momento perfecto"]'::jsonb, 'Un contexto compartido hace que tu entrada se sienta esperable y sea fácil responder.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4232f870-74a7-4557-9e29-70a586b48204', 'es', 'La ves en un bar. ¿Cuál es el acercamiento directo?', '["Comentar algo de la música o las bebidas para iniciar la conversación", "Mirarla a los ojos y sonreír", "“Me llamaste la atención y quería venir a presentarme”"]'::jsonb, 'Las aperturas directas dicen abiertamente y desde el principio que hay un interés romántico.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('478e1b59-9821-4b03-8744-b950a6269270', 'es', 'Ves a una mujer con un reloj antiguo. ¿Qué apertura genera participación?', '["“Hola, ¿cómo va tu noche?”", "“Te ves bien.”", "“¿A qué te dedicas?”", "“Ese reloj parece tener toda una historia detrás.”"]'::jsonb, 'Las suposiciones concretas la obligan a participar y responder de forma personal.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('48e4513c-c89e-4a8b-99e3-d70a28ea7193', 'es', 'Haciendo fila. Le dices: “Estás demasiado tranquila para esta fila”. Ella se ríe. ¿Qué está funcionando?', '["Hiciste referencia a la situación que comparten", "Creaste un contraste juguetón", "Le pediste permiso para hablar"]'::jsonb, 'Un contexto compartido con un toque juguetón baja la resistencia rápido.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4de13376-2210-4667-8d5f-ae59a38657c2', 'es', '¿Por qué es mejor aclarar su interés con un paso directo que quedarte dando vueltas?', '["Acorta la interacción", "Muestra liderazgo", "Evita el rechazo", "Le da claridad y el control a ella"]'::jsonb, 'Una frase clara elimina la ambigüedad: revela si su amabilidad es interés o simple cortesía.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4ef57d59-ef61-4420-92a6-2b920652d1b8', 'es', '¿Por qué las aperturas de opinión hacen que la gente se sienta valorada?', '["Al pedir su perspectiva, le dices explícitamente que su criterio importa", "Pedir opiniones demuestra inteligencia emocional y habilidades sociales", "A la gente le gusta más hablar de sí misma que escuchar"]'::jsonb, 'La gente se ilumina cuando su punto de vista importa. Sentirse valorada genera participación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4fe08740-af66-4896-aa93-6a50f2a41020', 'es', 'Te dice: “La verdad es que ya me iba”, pero se queda y sigue haciéndote preguntas.', '["Retirada cortés", "Señal mixta que tiende a abierta", "Señal fría suavizada por cortesía", "Rechazo rotundo"]'::jsonb, 'Que se quede y siga con curiosidad indica apertura, aunque tenga que irse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5027deaf-2157-42e1-b4db-138c9801e876', 'es', 'Sonríe, responde con buena actitud, pero dice: “La verdad es que estoy estudiando para un examen”.', '["Abierta: la buena respuesta muestra interés, aunque mencione el estudio", "Rechazo cortés: es amable, pero el estudio marca un límite", "Prueba: quiere ver si insistes o si respetas sus prioridades"]'::jsonb, 'Un tono amable puede ser cortesía; una prioridad dicha en voz alta es un límite. Deséale suerte y despídete.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('50916cec-9c9c-486c-b266-a45065ff3ea2', 'es', 'Responde con entusiasmo y te hace una pregunta, pero sigue revisando el celular.', '["Abierta: lo que dice muestra interés real, a pesar del celular", "Cortés: revisar el celular contradice la calidez de sus palabras y muestra una atención dividida", "Mixta: lo que dice es abierto, pero su comportamiento sugiere distracción"]'::jsonb, 'Las señales mixtas exigen leer la situación; sigue un poco más para ver si su atención vuelve.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51786178-0f86-4cb1-b4bd-0b3e68a87f9e', 'es', '¿Por qué es arriesgado confundir cortesía con interés?', '["Hace más lenta la interacción", "La somete a una presión que no quiere", "Hace que el acercamiento parezca atrevido"]'::jsonb, 'Su comodidad va primero; usa las señales para decidir cuándo seguir y cuándo aflojar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51944bdf-42d0-42e5-b902-ff0f21714718', 'es', 'Participa con calidez, se ríe, te hace preguntas, pero te dice: “La verdad es que tengo novio”.', '["Abierta: su participación muestra interés; lo del novio es una prueba", "Cortés: su calidez era simpatía, y lo del novio es un límite claro", "Mixta: muestra interés, pero su situación sentimental genera un conflicto"]'::jsonb, 'Estaba siendo amable, no mostrando interés romántico; mencionar a su novio es un límite claro.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51f130a3-2032-4c6f-b654-83d546e7b8aa', 'es', 'Fiesta. Ella es amable, pero no lo tienes claro. ¿Qué frases ayudan?', '["“Voy a pedir algo de tomar. ¿Vienes?”", "“Esta fiesta está un poco aburrida.”", "“Te dejo para que saludes a más gente.”", "“Ven, te presento a mis amigos.”"]'::jsonb, 'Las propuestas decididas comprueban, sin presión, si quiere moverse, sumarse o seguir.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('520ac978-94f9-404d-aabe-55099eebb89e', 'es', 'Ella menciona que estudió en el extranjero. ¿Qué respuesta evita tener una intención oculta?', '["Preguntarle con interés qué fue lo que más le gustó de allá", "Elogiar su aspecto para generar atracción", "Pedirle el número rápido", "Hablar solo de tus logros"]'::jsonb, 'Un interés genuino por su historia la hace sentirse vista, no perseguida.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('530f7582-4d63-4e0c-bede-bf88b8fdbd71', 'es', '¿Por qué decir “Solo me puedo quedar un momento” ayuda a quitar presión?', '["Sabe que no va a quedar atrapada en una conversación sin fin con un desconocido", "Demuestra que respetas su tiempo y no lo vas a desperdiciar", "El tiempo limitado crea urgencia"]'::jsonb, 'Un límite de tiempo indica que te irás pronto, y eso hace que baje la guardia.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('55289809-9c93-4056-aed5-077280b1ae2f', 'es', '¿Cuál es la principal fortaleza de las aperturas directas?', '["Te hacen sentir más seguro durante el acercamiento", "Aumentan la atracción gracias al atrevimiento", "Eliminan la ambigüedad porque dicen tu intención de inmediato"]'::jsonb, 'Ser directo elimina las adivinanzas y va directo a tu intención.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5645caed-20b5-412a-abcf-de263b1e3c46', 'es', 'Ella está mirando su celular. ¿Qué tiene que tener tu apertura para funcionar?', '["Ser educada", "Ser más fuerte", "Ser interesante", "Ser rápida e ingeniosa"]'::jsonb, 'Tu apertura tiene que ser más interesante que lo que ella estaba haciendo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('59132ed6-d432-4176-9308-5f83ffeb2e2c', 'es', '¿Por qué las sonrisas suelen confundir a los hombres al acercarse?', '["Una sonrisa siempre indica atracción", "Una sonrisa es una cortesía social por defecto", "Los hombres suponen que la calidez emocional es interés", "Ambas: las sonrisas suelen ser cortesía, y los hombres leen la calidez como interés"]'::jsonb, 'Las sonrisas suelen ser cortesía, y los hombres a menudo interpretan la calidez como atracción.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5a89ed7d-2ccb-4fb2-ad5a-c8b0d73aab44', 'es', 'Ella responde a tu apertura con cortesía, pero de forma breve. ¿Qué te permite seguir marcando el tono?', '["Hacerle otra pregunta interesante para llevar la conversación hacia delante", "Disculparte por interrumpir e irte", "Esperar a que ella te haga preguntas", "Igualar su energía baja y quedarte neutral"]'::jsonb, 'Tú decides el rumbo; sigue llevando la conversación en lugar de seguirla mientras se retira.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5b1abc4a-c6ad-4dd2-b4a0-e8c4cf55f119', 'es', '¿Por qué el cerebro lee el movimiento del cuerpo antes que las palabras?', '["Procesa primero el contenido verbal", "El movimiento indica por instinto la intención y si hay peligro", "Un movimiento fluido indica comodidad", "Un movimiento tenso delata ansiedad"]'::jsonb, 'Moverte relajado transmite que no hay peligro y le hace más fácil la interacción.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5b40af44-7fc8-4e4e-93fe-427ce1753d12', 'es', 'Bar. Abres la conversación. Ella apenas se gira, te dice un “hola” sin ganas y recorre el lugar con la mirada mientras hablas.', '["Cortés: es educada lo mínimo; sé breve o despídete", "Fría: desinterés claro; retírate de inmediato", "Prueba: quiere ver si mantienes tu actitud a pesar de su poca energía"]'::jsonb, 'El lenguaje corporal cerrado pesa más que las respuestas; da un paso atrás y vete con calma.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5bd1ec51-0293-467c-b328-37d4c947a52a', 'es', 'Los dos esperan en una fila larga para el café. ¿Qué aperturas indirectas podrías usar?', '["Preguntarle qué suele pedir aquí", "Elogiar su sonrisa", "Comentar lo lenta que va la fila", "Presentarte de inmediato"]'::jsonb, 'Las situaciones compartidas crean puntos de entrada naturales y sin presión.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5c6d17f6-baa9-4899-916b-fc9639e67f2c', 'es', 'Tiene en la mano un celular con una funda muy llamativa. ¿Qué podrías decir primero para despertar curiosidad?', '["“¿Dónde conseguiste esa funda?”", "“¿Te gusta tu celular?”", "“Qué interesante tu funda.”", "“Tengo una pregunta sobre esa funda.”"]'::jsonb, 'El planteamiento crea curiosidad antes de revelar la pregunta.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5e1e4ba0-77d1-47d1-b948-830f42c9bfc1', 'es', '¿Qué pasa cuando hablas acelerado durante una interacción?', '["Se pierde claridad", "Transmites tensión", "Se rompe el ritmo", "Todas las anteriores"]'::jsonb, 'Cuando atropellas las palabras, se pierde claridad y se nota la energía nerviosa. Baja el ritmo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5e77a13d-51fd-4fc8-8b20-e153be35f50a', 'es', '¿Qué suele indicar una respuesta cortés?', '["Le interesas, pero está poniendo a prueba tu seguridad y tu actitud", "Está siendo amable para evitar un enfrentamiento, aunque no tiene ningún interés", "No está segura o no está del todo abierta; avanza despacio o despídete"]'::jsonb, 'Cortés significa que no está segura o que está cerrada. Lee con atención sus siguientes señales.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5f79a125-3233-4761-a27a-0c3df5b785b6', 'es', '¿Qué pasa cuando pones un límite de tiempo?', '["La presión baja porque la interacción ya tiene una salida", "Se relaja al saber que no será un compromiso largo", "Creas una urgencia que hace que valore más la interacción"]'::jsonb, 'Los límites quitan el miedo a quedarse atrapada, y eso aumenta la comodidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('60bdd118-0868-4732-a177-bad97e1d37de', 'es', 'Tiene un pequeño tatuaje visible en la muñeca. ¿Qué podrías decir primero para despertar curiosidad?', '["“Qué buen tatuaje. ¿Qué es?”", "“Ese tatuaje se ve bien.”", "“Te tengo que preguntar por ese tatuaje.”", "“¿Tienes más tatuajes?”"]'::jsonb, 'El planteamiento crea curiosidad antes de revelar la pregunta.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('610a475a-54e4-4882-b442-6ebc0faac3a8', 'es', 'Los dos esperan en una fila larga para el café. ¿Qué apertura indirecta funciona mejor?', '["“Eres muy guapa, tenía que saludarte.”", "“¿Me das tu número?”", "“Esta fila está imposible hoy, ¿no?”", "“Tienes cara de necesitar un café.”"]'::jsonb, 'Un comentario sobre la situación se siente natural y quita presión.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('611e32cc-c038-42d3-a1ce-086d78cbcd68', 'es', 'Te responde con brevedad, aparta la mirada y mueve los pies. ¿Cuál es la mejor respuesta?', '["Hacerle preguntas más profundas", "Bromear un poco con ella", "Despedirte limpiamente", "Subir la energía"]'::jsonb, 'Las señales de retirada cortés significan que es hora de irte; despídete limpiamente y sin insistir.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('61e8562c-6ad4-4305-bf8f-d44fe44652ab', 'es', '¿Cuál es el cambio de mentalidad clave para acercarte movido por la curiosidad?', '["“¿Puedo sacar algo de esto?”", "“¿Esta persona me parece interesante?”", "“¿Cómo la impresiono rápido?”", "“¿Esto me va a llevar a una cita?”"]'::jsonb, 'El interés por su mundo elimina las intenciones ocultas y permite una participación genuina.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6212b078-0050-447a-bf0f-ff2070f3f00c', 'es', 'Fila de la cafetería. Abres la conversación. Ella sonríe un momento, dice “sí” y luego mira su celular.', '["Neutra: está distraída, pero podría participar si insistes", "Cortés: te reconoció, pero desvió la atención enseguida", "Fría: mirar el celular es una señal deliberada de rechazo"]'::jsonb, 'Te reconoció y luego marcó un límite; retírate sin alargarlo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('624f3918-37e1-4cec-8932-2afa6e870e81', 'es', 'Los dos están atrapados en una parada de autobús bajo la lluvia. ¿Qué apertura quita presión?', '["“Estás preciosa incluso bajo la lluvia.”", "“¿Quieres mi número?”", "“¿Puedo compartir tu paraguas?”", "“Qué tiempo tan horrible. ¿Sabes si el autobús viene tarde otra vez?”"]'::jsonb, 'Una experiencia compartida en ese momento inicia la conversación con naturalidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('645565d5-3468-40e0-a262-b135680333a7', 'es', 'Ves en su bolsa un llavero de un festival poco conocido. ¿Qué apertura muestra curiosidad?', '["“Qué buen llavero.”", "“Tu bolsa tiene personalidad.”", "“¿Viajas a eventos?”", "“¿Fuiste a ese festival? Dicen que es una locura.”"]'::jsonb, 'La curiosidad por sus experiencias invita a una conexión real, sin intenciones ocultas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('66e6b51f-4377-41cc-af99-be7fc8703380', 'es', 'Acercamiento de día en el gimnasio. Ella está descansando entre series. ¿Cuál es la mejor jugada?', '["Esperar a que termine por completo su entrenamiento para acercarte", "Entrar en su campo de visión, cruzar miradas, sonreír y acercarte durante el descanso", "Pedirle que te ayude con una serie o que revise tu técnica para tener una excusa natural", "El gimnasio no es lugar para esto; mejor no"]'::jsonb, 'El descanso entre series es una ventana corta; entra a la vista y con contacto visual para no sobresaltarla.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6854fe8c-37a2-4b05-abb5-8e28e81f85df', 'es', 'Acercamiento en la calle. Ella es amable, pero no lo tienes claro. ¿Qué frases ayudan a aclarar cuánto le interesas?', '["“Yo voy para allá de todos modos. ¿Me acompañas?”", "“¿Y adónde vas?”", "“¿Quieres que tomemos un café algún día?”", "“Pareces interesante.”"]'::jsonb, 'Las invitaciones a moverse o a verse en el futuro ponen a prueba su interés con hechos, no con cumplidos.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6ae58be8-fa28-4df9-982d-734c8bf6bc6b', 'es', 'El momento pasa y te arrepientes al instante. ¿Qué lo causó?', '["El rechazo por intentarlo", "Su falta de interés", "Una conversación que no llevó a nada", "Dejar pasar la oportunidad sin actuar"]'::jsonb, 'El arrepentimiento viene de las oportunidades perdidas, no de los intentos fallidos.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6c9441f0-7531-4148-a292-db648381ccf0', 'es', 'Librería. ¿Qué podrías decir como apertura de opinión?', '["“Necesito tu opinión: ¿un libro es un buen regalo?”", "“¿Sabes dónde está la sección de novelas?”", "“Disculpa, ¿estás leyendo algo interesante?”"]'::jsonb, 'Plantear que necesitas su criterio la hace sentirse valorada de inmediato.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6d84a13d-95e6-437d-9368-891c4d42990a', 'es', '¿Qué señales suelen indicar receptividad?', '["Te hace preguntas a ti también", "Se orienta hacia ti", "Responde a tus preguntas", "Una postura relajada"]'::jsonb, 'Que te devuelva preguntas y se oriente hacia ti muestra interés; tómalo como luz verde para seguir.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6e852fdc-853b-47ca-bd28-81f1c157b93e', 'es', '¿En qué ambientes funcionan mejor las aperturas directas?', '["Bares, discotecas, fiestas y eventos sociales", "Bibliotecas u oficinas tranquilas", "Supermercados en hora pico", "Trayectos en transporte público"]'::jsonb, 'La intención romántica se siente normal en ambientes sociales donde la gente espera conocer a otros.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6ead40bd-0dee-4b4c-935e-8cf034256a37', 'es', 'Discoteca. Le dices: “Me llamaste la atención”. Ella sonríe, te da las gracias, pero se vuelve hacia sus amigas.', '["Tocarle el hombro e intentar seguir la conversación", "Presentarte a sus amigas para seguir en la interacción", "Despedirte limpiamente: un reconocimiento sin participación es un rechazo cortés"]'::jsonb, 'Sonreír y darse la vuelta es un rechazo cortés. Quedarte después de eso demuestra que no sabes leer la situación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('702ce88e-2efa-49c5-9ee5-e08ed426d983', 'es', '¿Qué hace eficaces a las aperturas de curiosidad?', '["Invitan a dar su opinión o su perspectiva, no solo datos", "Son más interesantes que las preguntas de datos previsibles", "Abren temas sobre los que ella tiene algo que decir", "Todas las anteriores"]'::jsonb, 'Cuando la información está incompleta, el cerebro busca cerrarla; úsalo para atraer su atención.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('722e2188-0d60-460b-8ec7-ca6850661d5a', 'es', 'La ves con una funda de celular de colores vivos, pintada a mano. ¿Qué apertura genera participación?', '["“Qué buena funda.”", "“Tienes buen estilo.”", "“¿Qué hora es?”", "“Parece que esa funda la hiciste tú.”"]'::jsonb, 'Las suposiciones concretas la obligan a participar y responder de forma personal.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('727d61fb-ef06-4574-b2e1-63fb70f840c8', 'es', '¿Cuál es el objetivo principal de un buen planteamiento inicial?', '["Impresionar", "Eliminar el rechazo", "Despertar interés", "Evitar el silencio"]'::jsonb, 'El planteamiento inicial debe despertar curiosidad y participación emocional.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('732636f6-4948-4cf7-ab3c-1529a104b4c8', 'es', '¿Qué respuestas suelen significar que es hora de despedirte?', '["Respuestas de una sola palabra", "Darse la vuelta", "No te hace preguntas", "Responde a tus preguntas"]'::jsonb, 'Varias señales de desinterés juntas indican que es hora de irte.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('75d003ed-f14a-4b05-a68f-d5a813844935', 'es', 'Después de tu apertura, ella empieza a contarte lo que piensa con entusiasmo. ¿Qué haces?', '["Pedirle el número de inmediato", "Darle primero tu propia opinión", "Cambiar rápido de tema", "Escuchar y responder a su punto de vista"]'::jsonb, 'Construir sobre su respuesta premia su esfuerzo y mantiene vivo el ritmo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('761e81ae-f2b8-48ba-a7a0-a8ebe688a7e5', 'es', 'Acercamiento en la calle. Haces un comentario. Ella baja el ritmo, sonríe y camina a tu lado.', '["Se siente obligada a responderte", "Está abierta y elige seguir en la conversación", "Está neutral y esperando a que termines"]'::jsonb, 'Ajustar su paso al tuyo muestra que participa por voluntad propia; sigue adelante.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('77d7bb74-c3e1-4044-bfb0-c36b1415c65e', 'es', '¿Por qué deberías respetar sus señales aunque no sepas si es cortesía o receptividad?', '["Es mejor irte ante señales corteses que insistir ante señales frías", "Respetar la duda demuestra que sabes leer la situación", "Su comodidad importa más que tu necesidad de “asegurarte” de que le interesas", "Todas las anteriores"]'::jsonb, 'Ante la duda, respeta la señal de menor interés; prioriza su comodidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('78cf663a-b29b-480e-a8ef-fe1997c76016', 'es', 'Llegas y dices: “¿Les importa si me uno?”. Te dicen que claro, pero siguen con su conversación.', '["Esperar una pausa en su conversación y presentarte", "Hacer una broma para volver a captar su atención", "Despedirte: pediste entrar en su dinámica en lugar de crear la tuya"]'::jsonb, 'Cuando pides unirte, entras en su mundo; crea el tuyo abriendo con algo de contenido.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7b6ea2f2-5183-4215-9488-2a520d528b32', 'es', '¿Qué logra un contacto visual tranquilo y amable antes de hablar?', '["Genera una atracción intensa e inmediata", "La obliga a responder rápido", "Transmite sin palabras una intención positiva", "Oculta por completo tu acercamiento"]'::jsonb, 'Una mirada cálida y amable le confirma a su sistema nervioso que no hay peligro.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7b879d11-d60e-408e-b0dd-18f2dc6a1bab', 'es', 'Los dos esperan en el aeropuerto un vuelo con retraso. ¿Qué apertura quita presión?', '["“Te ves estresada. ¿Quieres conversar un rato?”", "“¿Me das tu número para la espera?”", "“Eres atractiva incluso con el retraso.”", "“Qué pesado este retraso. ¿Sabes cuánto va a durar?”"]'::jsonb, 'Una experiencia compartida en ese momento inicia la conversación con naturalidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7d344225-54cf-45ff-b8bc-1f401a89453f', 'es', '¿Qué transmite moverte con soltura?', '["Que sientes que perteneces al espacio en el que estás", "Que tu cuerpo no está transmitiendo tensión ni incomodidad", "Que ya practicaste esta situación de acercamiento antes"]'::jsonb, 'Un movimiento fluido transmite comodidad y que estás en tu lugar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7e53f4ec-68aa-4155-b6ff-8c9214acf8e2', 'es', '¿Cuál es la principal debilidad de las aperturas directas?', '["Solo funcionan en ciertos ambientes sociales", "Exigen más habilidad verbal que las indirectas", "Si no le atraes de inmediato, la interacción termina rápido"]'::jsonb, 'Las aperturas directas la ponen a evaluarte al instante. No hay confianza previa que amortigüe.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('80d3365a-d883-4997-8988-b8010451c01d', 'es', 'Te acercas, pero ella da un paso atrás de inmediato. ¿Cuál es la causa más probable?', '["Te acercaste demasiado o le bloqueaste el paso", "No le interesas y está poniendo distancia a propósito", "Tiene que ir a algún lado"]'::jsonb, 'Apartarse es una reacción refleja de protección, no un juicio deliberado.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('81df7422-a32e-4d7e-9ee5-03e32f5773ef', 'es', '¿Qué mecanismo psicológico hace eficaces las aperturas con una suposición?', '["Despiertan curiosidad por saber cómo llegaste a esa idea", "Halagan su ego", "Reducen el riesgo de rechazo"]'::jsonb, 'Las suposiciones despiertan curiosidad por cómo la percibes, y eso la mantiene mentalmente involucrada.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('862f73dc-ec2a-4136-a805-782b65c7eece', 'es', '¿A qué puede llevarte una sola conversación?', '["A amistades, relaciones u oportunidades que no esperabas", "A experiencias e historias que recordarás durante años", "A conocer a alguien que se vuelva importante en tu vida", "Todas las anteriores"]'::jsonb, 'Una conversación puede abrir posibilidades que van mucho más allá de ese momento.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('884ee9cb-5bc8-4593-8032-1bb68fe20856', 'es', 'Están los dos en un concierto. ¿Cuál es una apertura indirecta?', '["Preguntarle si ya había visto a esta banda o artista", "Comentar algo sobre cuánta gente hay o sobre el lugar", "Decirle que tiene muy buen gusto musical"]'::jsonb, 'Quedarte en la experiencia compartida deja que la comodidad crezca de forma natural.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('88ec90e6-280c-40aa-896c-018951f9446c', 'es', 'Está leyendo un libro cuya portada reconoces. ¿Qué apertura muestra curiosidad?', '["“Pareces alguien que lee mucho.”", "“¿Es la nueva edición? ¿Qué te está pareciendo?”", "“Buena elección, se nota que eres inteligente.”", "“¿Te importa si me siento contigo?”"]'::jsonb, 'La curiosidad por sus experiencias invita a una conexión real, sin intenciones ocultas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
